DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'AspNetIdentity') THEN
        CREATE SCHEMA "AspNetIdentity";
    END IF;
END $EF$;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'SnakeAid') THEN
        CREATE SCHEMA "SnakeAid";
    END IF;
END $EF$;


CREATE EXTENSION IF NOT EXISTS postgis;


CREATE TABLE "AspNetIdentity"."Accounts" (
    "Id" uuid NOT NULL,
    "FullName" character varying(200) NOT NULL,
    "AvatarUrl" character varying(1000),
    "FcmToken" character varying(512),
    "Role" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "IsActive" boolean NOT NULL,
    "ReputationPoints" integer NOT NULL,
    "ReputationStatus" integer NOT NULL,
    "SuspendedUntil" timestamp with time zone,
    "SuspensionReason" text,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_Accounts" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."AIModels" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Version" character varying(100) NOT NULL,
    "Description" character varying(1000),
    "IsActive" boolean NOT NULL,
    "IsDefault" boolean NOT NULL,
    "DeployedAt" timestamp with time zone,
    "RetiredAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AIModels" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."CatchingEnvironments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "Price" numeric(18,2) NOT NULL,
    "Currency" character varying(5) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_CatchingEnvironments" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."ExpertCertificates" (
    "Id" uuid NOT NULL,
    "ExpertId" uuid NOT NULL,
    "CertificateName" character varying(250) NOT NULL,
    "IssuingOrganization" character varying(250) NOT NULL,
    "IssueDate" timestamp with time zone NOT NULL,
    "ExpiryDate" timestamp with time zone,
    "CertificateUrl" text NOT NULL,
    "VerificationStatus" integer NOT NULL,
    "RejectionReason" character varying(500),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ExpertCertificates" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."FilterQuestions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Question" text NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_FilterQuestions" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."FirstAidGuidelines" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(255) NOT NULL,
    "Content" jsonb NOT NULL,
    "Type" integer NOT NULL,
    "Summary" character varying(500),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_FirstAidGuidelines" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."GeographicRegions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(200) NOT NULL,
    "Code" character varying(50) NOT NULL,
    "Description" character varying(1000),
    "Boundary" geography(Polygon, 4326) NOT NULL,
    "DisplayOrder" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_GeographicRegions" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."Lessons" (
    "Id" uuid NOT NULL,
    "Title" text NOT NULL,
    "Content" text NOT NULL,
    "Category" integer NOT NULL,
    "IsPublished" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Lessons" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."LocationEvents" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "SessionId" uuid NOT NULL,
    "SessionType" integer NOT NULL,
    "AccountId" uuid NOT NULL,
    "Role" integer NOT NULL,
    "Location" geometry NOT NULL,
    "RecordedAt" timestamp with time zone NOT NULL,
    "Speed" real,
    "Heading" real,
    CONSTRAINT "PK_LocationEvents" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."PaymentCards" (
    "Id" uuid NOT NULL,
    "CardNumber" text NOT NULL,
    "CardHolderName" text NOT NULL,
    "ExpiryDate" timestamp with time zone NOT NULL,
    "Cvv" text NOT NULL,
    "IsDefault" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PaymentCards" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."ReportMedias" (
    "Id" uuid NOT NULL,
    "ReferenceId" uuid,
    "ReferenceType" integer NOT NULL,
    "FileName" text NOT NULL,
    "MediaUrl" text NOT NULL,
    "ContentType" text NOT NULL,
    "FileSize" bigint NOT NULL,
    "Purpose" integer NOT NULL,
    "UploadBatchId" uuid,
    "SequenceOrder" integer,
    "RequiresAIProcessing" boolean NOT NULL,
    "IsProcessed" boolean NOT NULL,
    "ProcessedAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ReportMedias" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."ReputationRules" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "Points" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ReputationRules" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."SnakeSpecies" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ScientificName" character varying(500) NOT NULL,
    "Slug" character varying(200) NOT NULL,
    "CommonName" character varying(500) NOT NULL,
    "ImageUrl" character varying(2000) NOT NULL,
    "Description" character varying(2000) NOT NULL,
    "IdentificationSummary" character varying(2000) NOT NULL,
    "PrimaryVenomType" integer,
    "Identification" jsonb,
    "SymptomsByTime" jsonb,
    "FirstAidGuidelineOverride" jsonb,
    "RiskLevel" real NOT NULL,
    "IsVenomous" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_SnakeSpecies" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."Specializations" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Specializations" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."SystemSettings" (
    "SettingKey" character varying(100) NOT NULL,
    "Value" character varying(2000) NOT NULL,
    "Description" character varying(500),
    "ValueType" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_SystemSettings" PRIMARY KEY ("SettingKey")
);


CREATE TABLE "SnakeAid"."TrackingSessions" (
    "Id" uuid NOT NULL,
    "SessionId" uuid NOT NULL,
    "SessionType" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "MemberLocation" geometry(Point, 4326),
    "RescuerLocation" geometry(Point, 4326),
    "MemberLastUpdate" timestamp with time zone,
    "RescuerLastUpdate" timestamp with time zone,
    "DistanceMeters" double precision,
    "EtaMinutes" integer,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_TrackingSessions" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."TreatmentFacilities" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(200) NOT NULL,
    "Address" character varying(500) NOT NULL,
    "ContactNumber" character varying(20) NOT NULL,
    "Location" geometry(Point, 4326) NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_TreatmentFacilities" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."WorkShifts" (
    "Id" uuid NOT NULL,
    "Name" character varying(100) NOT NULL,
    "StartTime" interval NOT NULL,
    "EndTime" interval NOT NULL,
    "IsActive" boolean NOT NULL,
    "RequiredRescuers" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_WorkShifts" PRIMARY KEY ("Id")
);


CREATE TABLE "SnakeAid"."AppNotifications" (
    "Id" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "Title" text NOT NULL,
    "Message" text NOT NULL,
    "NotificationType" character varying(100) NOT NULL,
    "DeepLink" character varying(500),
    "PayloadJson" character varying(4000),
    "IsRead" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AppNotifications" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AppNotifications_Accounts_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetIdentity"."Accounts" ("Id") ON DELETE CASCADE
);


CREATE TABLE "SnakeAid"."Blogs" (
    "Id" uuid NOT NULL,
    "AuthorId" uuid NOT NULL,
    "Title" character varying(500) NOT NULL,
    "ThumbnailUrl" character varying(500) NOT NULL,
    "Content" text NOT NULL,
    "Category" integer NOT NULL,
    "Tags" integer[] NOT NULL,
    "ViewCount" integer NOT NULL,
    "LikeCount" integer NOT NULL,
    "ReadingTime" integer NOT NULL,
    "Status" integer NOT NULL,
    "RejectionReason" text,
    "LikedViewer" text[] NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Blogs" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Blogs_Accounts_AuthorId" FOREIGN KEY ("AuthorId") REFERENCES "AspNetIdentity"."Accounts" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "SnakeAid"."ExpertProfiles" (
