    CONSTRAINT "FK_ExpertProfiles_Accounts_AccountId" FOREIGN KEY ("AccountId") REFERENCES "AspNetIdentity"."Accounts" ("Id") ON DELETE CASCADE
);


CREATE TABLE "SnakeAid"."ExpertTimeSlots" (
    "Id" uuid NOT NULL,
