    CONSTRAINT "FK_MemberProfiles_Accounts_AccountId" FOREIGN KEY ("AccountId") REFERENCES "AspNetIdentity"."Accounts" ("Id") ON DELETE CASCADE
);


CREATE TABLE "SnakeAid"."OperatorProfiles" (
    "Id" uuid NOT NULL,
