    CONSTRAINT "FK_ReputationRawEvents_Accounts_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetIdentity"."Accounts" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "SnakeAid"."RescuerProfiles" (
    "AccountId" uuid NOT NULL,
