    CONSTRAINT "FK_UserFeedbacks_Accounts_RaterId" FOREIGN KEY ("RaterId") REFERENCES "AspNetIdentity"."Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_UserFeedbacks_Accounts_TargetUserId" FOREIGN KEY ("TargetUserId") REFERENCES "AspNetIdentity"."Accounts" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "AspNetIdentity"."UserLogins" (
