    CONSTRAINT "FK_UserLogins_Accounts_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetIdentity"."Accounts" ("Id") ON DELETE CASCADE
);


CREATE TABLE "AspNetIdentity"."UserTokens" (
    "UserId" uuid NOT NULL,
