    CONSTRAINT "FK_CommunityReports_SnakeSpecies_SnakeSpeciesId" FOREIGN KEY ("SnakeSpeciesId") REFERENCES "SnakeAid"."SnakeSpecies" ("Id")
);


CREATE TABLE "SnakeAid"."LibraryMedias" (
