    CONSTRAINT "FK_SnakeSpeciesNames_SnakeSpecies_SnakeSpeciesId" FOREIGN KEY ("SnakeSpeciesId") REFERENCES "SnakeAid"."SnakeSpecies" ("Id") ON DELETE CASCADE
);


CREATE TABLE "SnakeAid"."Antivenoms" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
